style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url("https://chat.openai.com/mnt/data/49f1acd9-2d69-4e58-97a6-504f9bf37925.png");
        background-size: cover;
        background-repeat: no-repeat;
        background-attachment: fixed;
        background-position: center;
        color: #333 !important;
    }

    /* Cuadros de contenido */
    .container, .content, .section, .game-card-container, .game-home-page-container {
        background-color: rgba(255, 255, 255, 0.8) !important;
        border-radius: 12px;
        padding: 12px;
    }

    /* Botones personalizados */
    button, .btn-primary {
        background-color: #ffc0cb !important;
        color: #fff !important;
        border-radius: 10px;
        border: none !important;
    }

    button:hover, .btn-primary:hover {
        background-color: #ff8da1 !important;
    }

    /* Eliminar fondo de header/footer */
    .header, .footer {
        background: transparent !important;
    }
}
